const reserva = $input.first().json[0];
const cliente = reserva.profiles;
const cancha = reserva.canchas;
const complejo = cancha.complejos;

// Formatear fecha en español
const fecha = new Date(reserva.fecha + 'T00:00:00');
const fechaFormateada = fecha.toLocaleDateString('es-AR', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

const horaInicio = reserva.hora_inicio.slice(0, 5);
const horaFin = reserva.hora_fin.slice(0, 5);

const metodoPago = reserva.metodo_pago === 'mercadopago' ? 'MercadoPago ✓' : 'Efectivo en el lugar';

return [{
  json: {
    telefono_cliente: cliente.telefono,
    nombre_cliente: cliente.nombre,
    mensaje_cliente: `✅ *¡Tu reserva está confirmada!*\n\n🏟️ *Complejo:* ${complejo.nombre}\n⚽ *Cancha:* ${cancha.nombre}\n📅 *Fecha:* ${fechaFormateada}\n⏰ *Horario:* ${horaInicio} a ${horaFin}\n💳 *Pago:* ${metodoPago}\n\n📍 *Dirección:* ${complejo.direccion || 'Consultar al complejo'}\n\n¡Nos vemos en la cancha! 🎉`,
    mensaje_admin: `🆕 *Nueva reserva confirmada*\n\n👤 *Cliente:* ${cliente.nombre}\n📞 *Teléfono:* ${cliente.telefono || 'No informado'}\n⚽ *Cancha:* ${cancha.nombre}\n📅 *Fecha:* ${fechaFormateada}\n⏰ *Horario:* ${horaInicio} a ${horaFin}\n💳 *Pago:* ${metodoPago}`,
    reserva_id: reserva.id
  }
}];
